use glam::{DVec3,DMat4};use ingetrazo_core::{mesh::Mesh,groups::Group,scene::SelectionItem,georef::GeoPath};use ingetrazo_gui::IngeTrazoApp;use ingetrazo_render::style::VisualStyle;
fn state(a:&IngeTrazoApp)->serde_json::Value{serde_json::json!({"style":a.scene.display_style,"shadows":a.scene.shadows,"undo":a.undo_stack.len(),"redo":a.redo_stack.len()})}
fn main(){let input=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let out=std::path::PathBuf::from(std::env::args().nth(2).unwrap());std::fs::create_dir_all(&out).unwrap();std::env::set_var("XDG_CONFIG_HOME",out.join("config"));let mut rows=serde_json::Map::new();for(nested,folded)in[(false,false),(false,true),(true,false),(true,true)]{let mut a=IngeTrazoApp::new();a.system_clipboard=None;a.open_document(&input.join("input.igz"));let mut mesh=Mesh::new();let v=[DVec3::ZERO,DVec3::X,DVec3::Y].map(|p|mesh.add_vertex(p));mesh.add_face(v.to_vec(),vec![]).unwrap();let mut g=Group::with_mesh("Leaf",mesh);g.transform=DMat4::from_translation(DVec3::new(10.,0.,0.));let id=g.id;a.scene.groups.push(g);a.scene.make_component(id).unwrap();if nested{let child=a.scene.groups.remove(0);let mut parent=Group::new("Parent");parent.children.push(child);a.scene.groups.push(parent);}a.scene.geo_paths.push(GeoPath::new(vec![DVec3::ZERO,DVec3::new(1.,2.,3.)],false,"Route"));a.scene.select(SelectionItem::Group(0));a.begin_component_edit();if nested{a.scene.select(SelectionItem::Group(0));a.begin_component_edit();}let entry=state(&a);a.save_undo_state();if folded{a.scene.mesh.vertices[0].position.x+=2.;}else{a.scene.geo_paths[0].points[1]=DVec3::new(8.,9.,10.);}a.scene.bump_version();a.style.visual_style=VisualStyle::Wireframe;a.style.back_edges_hidden=false;a.shadows_enabled=false;a.finish_component_edit();if nested{a.finish_component_edit();}let mut states=vec![state(&a)];a.undo();states.push(state(&a));a.redo();states.push(state(&a));rows.insert(format!("{}{}",if nested{"nested_"}else{""},if folded{"folded"}else{"ordinary"}),serde_json::json!({"entry":entry,"states":states}));}std::fs::write(out.join("native.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();}
